// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/entra/accounts", wrapper.GetEntraAccounts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entra/accounts/{objectId}/confirm", wrapper.PostEntraAccountsByObjectIdConfirm)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/entra/connection", wrapper.GetEntraConnection)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/entra/connection", wrapper.PutEntraConnection)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entra/connection/credentials", wrapper.PostEntraConnectionCredentials)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/entra/connection/credentials/{id}", wrapper.DeleteEntraConnectionCredentialsById)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/entra/connection/settings", wrapper.PutEntraConnectionSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/entra/connection/skus", wrapper.GetEntraConnectionSkus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entra/connection/test", wrapper.PostEntraConnectionTest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/entra/events", wrapper.GetEntraEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/entra/groups", wrapper.GetEntraGroups)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entra/groups/{objectId}/confirm", wrapper.PostEntraGroupsByObjectIdConfirm)

	return m
}

